34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	const LOYALTY_YEARS = 2;
51	const LOYALTY_DISCOUNT_PERCENT = 20;
52	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
53	
54	const applyPercent = (amount: number, percent: number): number =>
55	  (amount * percent) / ONE_HUNDRED_PERCENT;
56	
57	const addSurcharge = (amount: number, surchargePercent: number): number =>
58	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
59	
60	const applyDiscount = (amount: number, discountPercent: number): number =>
61	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
62	
63	const COMPONENT_TYPES = ["rune", "moonstone"];
64	const BUILDING_BLOCK_SIZE = 3;
65	const BUILDING_BLOCK_BASE_PREMIUM = 60;
66	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
67	
68	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	// Risk surcharges are per-item properties of the insured object, each raising
71	// that item's premium by a percentage. They stack multiplicatively: an item
72	// matching two rules is surcharged by the first, then by the second.
73	interface RiskSurcharge {
74	  appliesTo: (item: Item) => boolean;
75	  percent: number;
76	}
77	
78	const RISK_SURCHARGES: RiskSurcharge[] = [
79	  { appliesTo: (item) => item.cursed === true, percent: 50 },
80	  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
81	];
82	
83	const riskAdjustedPremiumOf = (item: Item): number =>
84	  RISK_SURCHARGES.reduce(
85	    (premium, surcharge) =>
86	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
87	    basePremiumOf(item),
88	  );
89	
90	const sumRiskAdjustedPremiums = (items: Item[]): number =>
91	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
92	
93	// Alike components are grouped into building blocks of 3, which carry a
94	// special base premium; the remaining components are priced individually,
95	// risk surcharges and all.
96	// Total over the empty group: no components means no blocks and no remainder.
97	const alikeComponentsPremium = (components: Item[]): number => {
98	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
99	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
100	  return (
101	    blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumRiskAdjustedPremiums(unblocked)
102	  );
103	};
104	
105	const groupByType = (items: Item[]): Item[][] => [
106	  ...items
107	    .reduce(
108	      (groups, item) =>
109	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	// Components and main items are priced by different rules, so each group is
116	// totalled separately: components by building block, main items item by item.
117	const componentsPremium = (components: Item[]): number =>
118	  groupByType(components).reduce(
119	    (total, alike) => total + alikeComponentsPremium(alike),
120	    0,
121	  );
122	
123	// The sum insured is what the items alone are worth to MHPCO, before any
124	// modifier that depends on the customer or the contract they sit in.
125	const sumInsuredOf = (items: Item[]): number =>
126	  sumRiskAdjustedPremiums(items.filter((item) => !isComponent(item))) +
127	  componentsPremium(items.filter(isComponent));
128	
129	// Contract-level modifiers adjust the sum insured by the terms of the deal
130	// rather than the nature of the items. Like risk surcharges they stack
131	// multiplicatively, each applying to the result of the one before, so they are
132	// written the same way: a predicate over the contract, and an adjustment.
133	interface Contract {
134	  customer: Customer;
135	  isFirstContract: boolean;
136	}
137	
138	interface ContractModifier {
139	  appliesTo: (contract: Contract) => boolean;
140	  adjust: (amount: number) => number;
141	}
142	
143	// A first insurance is assessed, a later one rewarded — the two predicates are
144	// exhaustive and mutually exclusive, so exactly one of them always applies.
145	const CONTRACT_MODIFIERS: ContractModifier[] = [
146	  {
147	    appliesTo: ({ isFirstContract }) => isFirstContract,
148	    adjust: (amount) => addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT),
149	  },
150	  {
151	    appliesTo: ({ isFirstContract }) => !isFirstContract,
152	    adjust: (amount) =>
153	      applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT),
154	  },
155	  {
156	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
157	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
158	  },
159	];
160	
161	const contractAdjustedPremiumOf = (
162	  sumInsured: number,
163	  contract: Contract,
164	): number =>
165	  CONTRACT_MODIFIERS.reduce(
166	    (premium, modifier) =>
167	      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
168	    sumInsured,
169	  );
170	
171	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
172	// so that no percentage ever applies to it.
173	const billedPremiumOf = (premium: number): number =>
174	  Math.ceil(premium) + ADMIN_FEE;
175	
176	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
177	  premium: billedPremiumOf(
178	    contractAdjustedPremiumOf(sumInsuredOf(step.items), contract),
179	  ),
180	});
181	
182	export const runScenario = (scenario: Scenario): ScenarioResult => ({
183	  results: scenario.steps.map((step, index) =>
184	    quote(step, { customer: scenario.customer, isFirstContract: index === 0 }),
185	  ),
186	});
