// Splits items into those matching the predicate and the rest, in one pass,
// so the two halves are complementary by construction.
const partition = <T>(
  values: T[],
  matches: (value: T) => boolean,
): [T[], T[]] =>
  values.reduce<[T[], T[]]>(
    ([matched, rest], value) =>
      matches(value)
        ? [[...matched, value], rest]
        : [matched, [...rest, value]],
    [[], []],
  );

